package store

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"github.com/fake-fantasy-online-group/fake-fantasy-online-server/server/internal/domain"
	"github.com/jackc/pgx/v5"
)

// MailOperation is generated by the server before an actor reserves assets. Its
// identity survives every database attempt; it is never regenerated on retry.
type MailOperation struct {
	ID     string
	Kind   string
	MailID int64
	Draft  domain.MailDraft
	Rule   domain.MailRule
}

type MailOperationStore interface {
	CheckMailOperations(context.Context) error
	CommitMailOperation(context.Context, MailOperation, domain.Snapshot) error
	ResolveMailOperation(context.Context, MailOperation, domain.Snapshot) (bool, error)
}

var ErrMailOperationAborted = errors.New("mail: operation was durably aborted")

// SettleMailOperation must run while the caller owns the character's ordered
// write slot. Cancellation is not evidence of rollback. After an unsuccessful
// attempt, keep that slot and the actor reservation until the database proves
// the outcome. Other character slots may continue independently.
func SettleMailOperation(ctx context.Context, st MailOperationStore, op MailOperation, before, candidate domain.Snapshot) error {
	attempt, cancel := context.WithTimeout(ctx, 5*time.Second)
	cause := st.CommitMailOperation(attempt, op, candidate)
	cancel()
	if cause == nil {
		return nil
	}
	slog.Warn("邮件提交结果待确认，保留角色物权", "operation", op.ID, "kind", op.Kind, "err", cause)
	delay := 100 * time.Millisecond
	for {
		check, stop := context.WithTimeout(context.Background(), 5*time.Second)
		committed, err := st.ResolveMailOperation(check, op, before)
		stop()
		if err == nil {
			if committed {
				return nil
			}
			return cause
		}
		slog.Warn("邮件物权确认失败，继续保留角色物权", "operation", op.ID, "err", err)
		time.Sleep(delay)
		if delay < 3*time.Second {
			delay *= 2
		}
	}
}

func mailOperationDigest(op MailOperation, snap domain.Snapshot) (string, error) {
	if snap.Char == nil || snap.Char.ID <= 0 || len(op.ID) != 32 {
		return "", fmt.Errorf("mail: invalid operation identity")
	}
	if _, err := hex.DecodeString(op.ID); err != nil {
		return "", fmt.Errorf("mail: invalid operation ID: %w", err)
	}
	if op.Kind != "send" && op.Kind != "claim" {
		return "", fmt.Errorf("mail: invalid operation kind")
	}
	if op.Kind == "send" && !op.Rule.Valid() || op.Kind == "claim" && op.MailID <= 0 {
		return "", fmt.Errorf("mail: invalid operation request")
	}
	data, err := json.Marshal(struct {
		Operation MailOperation
		Character int64
	}{op, snap.Char.ID})
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:]), nil
}

// Locking before reading the receipt is essential: an earlier COMMIT with a
// lost acknowledgement may still be executing. An absent receipt is evidence
// of rollback only after the same transaction lock has been acquired.
func mailOperationReceipt(ctx context.Context, tx *pgTx, op MailOperation, charID int64, digest string) (exists, committed bool, err error) {
	if _, err = tx.tx.Exec(ctx, `SELECT pg_advisory_xact_lock(hashtextextended($1,0))`, "mail:"+op.ID); err != nil {
		return
	}
	var storedDigest string
	var storedChar int64
	err = tx.tx.QueryRow(ctx, `SELECT char_id,digest,committed FROM mail_operation_receipts WHERE operation_id=$1`, op.ID).Scan(&storedChar, &storedDigest, &committed)
	if errors.Is(err, pgx.ErrNoRows) {
		return false, false, nil
	}
	if err != nil {
		return false, false, err
	}
	if storedChar != charID || storedDigest != digest {
		return false, false, fmt.Errorf("mail: operation receipt identity mismatch")
	}
	return true, committed, nil
}

func saveMailOperationReceipt(ctx context.Context, tx *pgTx, op MailOperation, charID int64, digest string, committed bool) error {
	_, err := tx.tx.Exec(ctx, `INSERT INTO mail_operation_receipts(operation_id,char_id,kind,digest,committed) VALUES($1,$2,$3,$4,$5)`, op.ID, charID, op.Kind, digest, committed)
	return err
}

func (p *Postgres) CommitMailOperation(ctx context.Context, op MailOperation, candidate domain.Snapshot) error {
	digest, err := mailOperationDigest(op, candidate)
	if err != nil {
		return err
	}
	return p.WithTx(ctx, func(raw Store) error {
		tx := raw.(*pgTx)
		exists, committed, err := mailOperationReceipt(ctx, tx, op, candidate.Char.ID, digest)
		if err != nil {
			return err
		}
		if exists {
			if committed {
				return nil
			}
			return ErrMailOperationAborted
		}
		switch op.Kind {
		case "send":
			_, err = sendMailTx(ctx, tx, candidate, op.Draft, op.Rule)
		case "claim":
			err = claimMailTx(ctx, tx, candidate, op.MailID)
		}
		if err != nil {
			return err
		}
		return saveMailOperationReceipt(ctx, tx, op, candidate.Char.ID, digest, true)
	})
}

func (p *Postgres) ResolveMailOperation(ctx context.Context, op MailOperation, before domain.Snapshot) (bool, error) {
	digest, err := mailOperationDigest(op, before)
	if err != nil {
		return false, err
	}
	var committed bool
	err = p.WithTx(ctx, func(raw Store) error {
		tx := raw.(*pgTx)
		exists, outcome, err := mailOperationReceipt(ctx, tx, op, before.Char.ID, digest)
		if err != nil {
			return err
		}
		if exists {
			committed = outcome
			return nil
		}
		// The previous transaction is gone and did not commit. Persist the baseline
		// before releasing the queue slot, including any earlier coalesced saves.
		if err := tx.SaveSnapshot(ctx, before); err != nil {
			return err
		}
		return saveMailOperationReceipt(ctx, tx, op, before.Char.ID, digest, false)
	})
	return committed, err
}

// CheckMailOperations prevents reserving assets before migration 87 is present.
// Successful readiness is cached for this store lifetime; failures can recover
// after deployment without a process restart. Dropping live tables is unsupported.
func (p *Postgres) CheckMailOperations(ctx context.Context) error {
	if p.mailOperationsReady.Load() {
		return nil
	}
	_, err := p.pool.Exec(ctx, `SELECT operation_id,char_id,kind,digest,committed FROM mail_operation_receipts LIMIT 0`)
	if err != nil {
		return fmt.Errorf("mail: migration 000000_init-87.sql required before asset operations: %w", err)
	}
	p.mailOperationsReady.Store(true)
	return nil
}
